// SACRED independent one-key statues. Match each inserted-key prop's socket/animation.
$Event(5750350, Restart, function(unlockFlag, statue, keyAsset, acceptedFlag, rejectedFlag, socket, animationId, animationSeconds) {
    DisableNetworkSync();
    DeleteAssetfollowingSFX(statue, true);
    if (EventFlag(unlockFlag)) {
        EnableAsset(keyAsset);
        EndEvent();
    }
    DisableAsset(keyAsset);
    SetEventFlagID(acceptedFlag, OFF);
    SetEventFlagID(rejectedFlag, OFF);
    CreateAssetfollowingSFX(statue, socket, 806040);
    WaitFor(EventFlag(unlockFlag)
        || (PlayerIsInOwnWorld() && ActionButtonInArea(9220, statue)));
    if (!EventFlag(unlockFlag)) {
        DisplayGenericDialogAndSetEventFlags(108000, PromptType.YESNO, NumberofOptions.TwoButtons,
            statue, 1.75, acceptedFlag, rejectedFlag, rejectedFlag);
        if (!EventFlag(acceptedFlag)) {
            WaitFixedTimeSeconds(0.5);
            RestartEvent();
        }
        StoreItemAmountHeldInEventValue(ItemType.Goods, 8000, 9580, 8);
        if (EventValue(9580, 8) < 1) {
            ForceAnimationPlayback(10000, 50050, false, false, false);
            WaitFixedTimeSeconds(1.4);
            DisplayGenericDialog(308000, PromptType.OKCANCEL, NumberofOptions.NoButtons, statue, 3);
            RestartEvent();
        }
        IssueShortWarpRequest(10000, TargetEntityType.Asset, statue, 191);
        ForceAnimationPlayback(10000, animationId, false, false, false);
        WaitFixedTimeSeconds(animationSeconds);
        RemoveItemFromPlayer(ItemType.Goods, 8000, 1);
        SetNetworkconnectedEventFlagID(unlockFlag, ON);
        DisplayGenericDialog(208000, PromptType.OKCANCEL, NumberofOptions.NoButtons, statue, 3);
    }
    EnableAsset(keyAsset);
    DeleteAssetfollowingSFX(statue, true);
});

// SACRED paired torch assets; restore the saved state on load/rest for every player.
$Event(5750351, Restart, function(stateFlag, beforeAsset, afterAsset, resetAfterHadeon) {
    DisableNetworkSync();
    // Victory overrides either statue's activation, including on reload.
    if (resetAfterHadeon == 1 && EventFlag(1055420915)) {
        DisableAsset(afterAsset);
        EnableAsset(beforeAsset);
        EndEvent();
    }
    if (EventFlag(stateFlag)) {
        DisableAsset(beforeAsset);
        EnableAsset(afterAsset);
        EndIf(resetAfterHadeon == 0);
        WaitFor(EventFlag(1055420915));
        RestartEvent();
    }
    DisableAsset(afterAsset);
    EnableAsset(beforeAsset);
    WaitFor(EventFlag(stateFlag) || (resetAfterHadeon == 1 && EventFlag(1055420915)));
    RestartEvent();
});

