    ClearSpEffect(18000850, 5801);
    ClearSpEffect(18000850, 5805);
    ClearSpEffect(18000850, 1627117);
    ClearSpEffect(18000850, 1627116);
    ClearSpEffect(18000850, 1627120);
    SetEventFlagID(18002851, OFF);
    EnableCharacterAI(18000850);
    RequestCharacterAIReplan(18000850);
    EndEvent();
L9:
    SetEventFlagID(18002851, OFF);
    SetEventFlagID(18002852, OFF);
    ClearSpEffect(18000850, 1627116);
    ClearSpEffect(18000850, 1627120);
    ClearSpEffect(18000850, 1627117);
    ClearSpEffect(18000850, 1627118);
    ClearSpEffect(18000851, 1627116);
    ClearSpEffect(18000851, 1627118);
