// Hadeon progression: saved cumulative failures survive reloads; temporary
// latches prevent repeated processing. Victory has priority on simultaneous death.
$Event(5750420, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    EndIf(EventFlag(1055420915));
    WaitFor(EventFlag(1055420915) || (!EventFlag(1055425224)
        && EventFlag(1055422933) && CharacterHPValue(18002354) > 0
        && CharacterHPValue(10000) <= 0
        && (CharacterDead(10000) || EventFlag(1055425042))
        && !CharacterHasSpEffect(10000, 1627125) && PlayerInMap(18, 0, 0, 0)
        // Fatal arena falls are combat losses; merely entering the fall region is not.
        && (InArea(10000, 18002367) || (InArea(10000, 18000359)
            && !InArea(10000, 18000361) && !InArea(10000, 18000362)
            && !InArea(10000, 18002348) && !InArea(10000, 18002349)
            && !InArea(10000, 18002375)))));
    // Adjacent-frame fatal hits resolve before the saved progression changes.
    WaitFixedTimeFrames(1);
    EndIf(EventFlag(1055420915) || CharacterHPValue(18002354) <= 0);
    RestartIf(CharacterHPValue(10000) > 0 || CharacterHasSpEffect(10000, 1627125)
        || !EventFlag(1055422933)
        || (!CharacterDead(10000) && !EventFlag(1055425042))
        || !PlayerInMap(18, 0, 0, 0)
        || (!InArea(10000, 18002367) && (!InArea(10000, 18000359)
            || InArea(10000, 18000361) || InArea(10000, 18000362)
            || InArea(10000, 18002348) || InArea(10000, 18002349)
            || InArea(10000, 18002375))));
    SetEventFlagID(1055425224, ON);
    SetEventFlagID(1055425225, OFF);
    SetEventFlagID(1055425218, OFF);
    if (!EventFlag(1055420930)) {
        SetEventFlagID(1055420930, ON);
    }
    else if (!EventFlag(1055420931)) {
        SetEventFlagID(1055420931, ON);
    }
    else if (!EventFlag(1055420932)) {
        SetEventFlagID(1055420932, ON);
    }
    else if (!EventFlag(1055420933)) {
        SetEventFlagID(1055420933, ON);
    }
    else if (!EventFlag(1055420934)) {
        SetEventFlagID(1055420934, ON);
    }
    else if (!EventFlag(1055420952)) {
        SetEventFlagID(1055420952, ON);
    }
    else if (!EventFlag(1055420953)) {
        SetEventFlagID(1055420953, ON);
    }
    else if (!EventFlag(1055420954)) {
        SetEventFlagID(1055420954, ON);
    }
    else if (!EventFlag(1055420955)) {
        SetEventFlagID(1055420955, ON);
    }
    else if (!EventFlag(1055420956)) {
        SetEventFlagID(1055420956, ON);
    }
    // Record the loss first so the third fatality can select the new line.
    // Falling below the arena still advances progression without a kill taunt.
    if (!InArea(10000, 18002367)) {
        SetEventFlagID(1055425220, ON);
    }
    WaitFor(CharacterHPValue(10000) > 0 || EventFlag(1055420915));
    SetEventFlagID(1055425224, OFF);
    RestartEvent();
});

