// Final phrase uses a fresh positional emitter while the subtitle timeline stays active.
$Event(5750433, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    WaitFor(EventFlag(1055422946) && EventFlag(1055425200));
    WaitFor(ElapsedSeconds(13.10) || AnyBatchEventFlags(1055425220, 1055425222)
        || !EventFlag(1055422946) || !EventFlag(1055425200) || EventFlag(1055422948)
        || (!EventFlag(1055422933) && !EventFlag(1055422947))
        || CharacterDead(10000) || EventFlag(1055425042)
        || CharacterHPValue(18002354) <= 0 || EventFlag(1055420915));
    if (!AnyBatchEventFlags(1055425220, 1055425222)
        && EventFlag(1055422946) && EventFlag(1055425200) && !EventFlag(1055422948)
        && (EventFlag(1055422933) || EventFlag(1055422947))
        && !CharacterDead(10000) && !EventFlag(1055425042)
        && CharacterHPValue(18002354) > 0 && !EventFlag(1055420915)) {
        PlaySE(18002354, SoundType.Voice, 999800003);
    }
    // At most one post per voice activation, including cancellation races.
    WaitFor(!EventFlag(1055422946) || !EventFlag(1055425200));
    RestartEvent();
});

// Hidden sound carrier follows the native 18000852 pattern in this map. It has
// no combat or talk role and outlives Hadeon's corpse until the voice tail ends.
$Event(5750431, Restart, function() {
    DisableNetworkSync();
    DisableCharacter(18002390);
    DisableCharacterAI(18002390);
    DisableCharacterCollision(18002390);
    DisableCharacterGravity(18002390);
    EnableCharacterInvincibility(18002390);
    if (!EventFlag(1055420915)) {
        SetCharacterBackreadState(18002390, false);
        EnableCharacterDefaultBackread(18002390);
        WaitFor(EventFlag(1055420915) || EventFlag(1055425256));
        WaitFor(EventFlag(1055425256) || ElapsedSeconds(25));
    }
    DisableCharacterDefaultBackread(18002390);
    SetCharacterBackreadState(18002390, true);
});

// Queue one half-health line per attempt; never stop combat for speech.
$Event(5750421, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    EndIf(EventFlag(1055420915));
    WaitFor(EventFlag(1055420915) || (!EventFlag(1055425225)
        && EventFlag(1055422933) && CharacterHPValue(10000) > 0
        && CharacterHPValue(18002354) > 0 && HPRatio(18002354) <= 0.5
        && PlayerInMap(18, 0, 0, 0)
            && InArea(10000, 18000359) && !InArea(10000, 18002367)
            && !InArea(10000, 18000361) && !InArea(10000, 18000362)
            && !InArea(10000, 18002348) && !InArea(10000, 18002349)
            && !InArea(10000, 18002375)));
    EndIf(EventFlag(1055420915));
    SetEventFlagID(1055425225, ON);
    SetEventFlagID(1055425218, ON);
    WaitFixedTimeFrames(1);
    RestartEvent();
});

// Capture entitlement before another worker clears combat state. Existing
// completed saves cannot earn this retroactively; both death paths check boss HP.
$Event(5750422, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    EndIf(EventFlag(1055420915));
    WaitFor(EventFlag(1055422947) || EventFlag(1055422933));
    WaitFor(CharacterHPValue(18002354) <= 0);
    WarpCharacterAndCopyFloor(18002390, TargetEntityType.Character, 18002354, 900, 18002354);
    SetEventFlagID(1055425226, ON);
    if (!EventFlag(1055420930)) {
        SetEventFlagID(1055420937, ON);
        SetEventFlagID(1055425222, ON);
    } else {
        SetEventFlagID(1055425221, ON);
    }
    EndEvent();
});

// Award through the original lot: its own receipt also gates the world pickup.
// Persistent entitlement makes a missed delivery recoverable after a reload.
$Event(5750423, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    EndIf(EventFlag(1055420250));
    WaitFor(EventFlag(1055420937) && EventFlag(1055420915)
        && CharacterHPValue(10000) > 0 && !CharacterDead(10000));
    EndIf(EventFlag(1055420250));
    AwardItemLot(10000320);
    EndEvent();
});

// This direct HKS guard complements the common permission worker. It remains
// room-scoped so the beginner rescue still works elsewhere in the opening.
$Event(5750424, Restart, function() {
    DisableNetworkSync();
    EndIf(!PlayerIsInOwnWorld());
    SetEventFlagID(1055425223, OFF);
    EndIf(EventFlag(1055420915));
    if (!EventFlag(1055420930) && PlayerInMap(18, 0, 0, 0)
        && InArea(10000, 18000359) && !InArea(10000, 18002367)) {
        SetEventFlagID(1055425223, ON);
        ClearSpEffect(10000, 1627122);
        ClearSpEffect(10000, 1627123);
    }
    WaitFixedTimeFrames(1);
    RestartEvent();
});

// SACRED Hadeon presence: short-lived, host-only permission for deflect thorns.
$Event(5750305, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    if (!EventFlag(1055420915) && EventFlag(1055422933)
        && CharacterHPValue(18002354) > 0 && CharacterHPValue(10000) > 0
        && InArea(10000, 18000359) && !InArea(10000, 18002367)
        && !InArea(18002354, 18002367)) {
        SetSpEffect(10000, 1627102);
    } else {
        ClearSpEffect(10000, 1627102);
    }
    EndIf(EventFlag(1055420915));
    if (EventFlag(1055425042) && CharacterHPValue(10000) <= 0) {
        BatchSetEventFlags(1055422930, 1055422932, OFF);
        ClearSpEffect(10000, 1627103);
    }
    WaitFixedTimeSeconds(0.05);
    RestartEvent();
});

// SACRED Hadeon milestones: Thorn Ward at 75% and 50%, shriek at 25%.
$Event(5750306, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    EndIf(EventFlag(1055420915));
    WaitFor(EventFlag(1055420915) || (EventFlag(1055422933) && EventFlag(1055420930)
        && CharacterHPValue(18002354) > 0 && CharacterHPValue(10000) > 0
        && InArea(10000, 18000359) && !InArea(10000, 18002367)
        && !InArea(18002354, 18002367)
        && ((!EventFlag(1055422930) && HPRatio(18002354) <= 0.75)
            || (!EventFlag(1055422931) && HPRatio(18002354) <= 0.50)
            || (!EventFlag(1055422932) && HPRatio(18002354) <= 0.25))));
    EndIf(EventFlag(1055420915));
    if (!EventFlag(1055420930) || !EventFlag(1055422933) || CharacterHPValue(10000) <= 0
        || CharacterHPValue(18002354) <= 0 || !InArea(10000, 18000359)
        || InArea(10000, 18002367) || InArea(18002354, 18002367)) {
        RestartEvent();
    }
    SetSpEffect(10000, 1626986);
    SetSpEffect(10000, 1626991);
    SetSpEffect(10000, 1626993);
    if (!EventFlag(1055422930) && HPRatio(18002354) <= 0.75) {
        SetEventFlagID(1055422930, ON);
        SetSpEffect(10000, 1626926);
        ClearSpEffect(10000, 1626916);
        ClearSpEffect(10000, 1626917);
        ClearSpEffect(10000, 1626918);
        ClearSpEffect(10000, 1626926);
        SetSpEffect(10000, 1626915);
        $InitializeEvent(0, 5750340);
        SetSpEffect(10000, 1626916);
        $InitializeEvent(0, 5750308);
    }
    if (!EventFlag(1055422931) && HPRatio(18002354) <= 0.50) {
        SetEventFlagID(1055422931, ON);
        SetSpEffect(10000, 1626926);
        ClearSpEffect(10000, 1626916);
        ClearSpEffect(10000, 1626917);
        ClearSpEffect(10000, 1626918);
        ClearSpEffect(10000, 1626926);
        SetSpEffect(10000, 1626915);
        $InitializeEvent(0, 5750340);
        SetSpEffect(10000, 1626916);
        $InitializeEvent(0, 5750308);
    }
    if (!EventFlag(1055422932) && HPRatio(18002354) <= 0.25) {
        PlaySE(10000, SoundType.SFX, 530181);
        WaitFixedTimeSeconds(0.1);
        PlaySE(10000, SoundType.SFX, 450264);
        PlaySE(10000, SoundType.SFX, 450264);
        WaitFixedTimeSeconds(0.2);
        // No delayed grant or damage after death, retreat, victory or a fall.
        if (!EventFlag(1055420915) && EventFlag(1055422933)
            && CharacterHPValue(18002354) > 0 && CharacterHPValue(10000) > 0
            && InArea(10000, 18000359) && !InArea(10000, 18002367)
            && !InArea(18002354, 18002367)) {
            SetEventFlagID(1055422932, ON);
            SetSpEffect(10000, 1626976);
            SetSpEffect(18002354, 1627101); // 10% maximum HP, independent of AoE contact.
        }
    }
    WaitFixedTimeSeconds(0.05);
    RestartEvent();
});

