// Shared Hadeon death confirmation. A rescue may briefly pass through zero HP.
// This is temporary encounter state, not a vanilla death or progression flag.
$Event(5750402, Restart, function() {
    EndIf(!PlayerIsInOwnWorld());
    SetEventFlagID(1055425042, OFF);
    WaitFor(CharacterHPValue(10000) <= 0);
    WaitFor(ElapsedSeconds(0.5) || CharacterHPValue(10000) > 0);
    RestartIf(CharacterHPValue(10000) > 0 || CharacterHasSpEffect(10000, 1627125));
    SetEventFlagID(1055425042, ON);
    WaitFor(CharacterHPValue(10000) > 0);
    RestartEvent();
});

// Host-only Hadeon aid permission; expiry also handles map departure/reload.
$Event(5750403, Restart, function() {
    DisableNetworkSync();
    EndIf(!PlayerIsInOwnWorld());
    SetEventFlagID(1055425233, OFF);
    ClearSpEffect(10000, 1627130);
    WaitFor(EventFlag(1055420915) || (EventFlag(1055420930) && CharacterHPValue(10000) > 0
        && CharacterHPValue(18002354) > 0
        && InArea(10000, 18000359) && !InArea(10000, 18002367)
        && !EventFlag(1055425042) && !CharacterHasSpEffect(10000, 100690)
        && !CharacterHasSpEffect(10000, 9621)));
    EndIf(EventFlag(1055420915));
    // Eligibility must remain continuous before the existing ten-second HKS ramp begins.
    WaitFor(ElapsedSeconds(3) || CharacterHPValue(18002354) <= 0
        || !InArea(10000, 18000359) || InArea(10000, 18002367)
        || EventFlag(1055420915) || EventFlag(1055425042)
        || CharacterHasSpEffect(10000, 100690) || CharacterHasSpEffect(10000, 9621));
    RestartIf(EventFlag(1055420915) || CharacterHPValue(18002354) <= 0
        || !InArea(10000, 18000359) || InArea(10000, 18002367)
        || EventFlag(1055425042) || CharacterHasSpEffect(10000, 100690)
        || CharacterHasSpEffect(10000, 9621));
    // Admission must outlive a missed refresh of the short-lived permission effect.
    SetEventFlagID(1055425233, ON);
    SetSpEffect(10000, 1627130);
    WaitFor(EventFlag(1055420915) || CharacterHPValue(18002354) <= 0
        || !InArea(10000, 18000359) || InArea(10000, 18002367)
        || EventFlag(1055425042) || CharacterHasSpEffect(10000, 100690)
        || CharacterHasSpEffect(10000, 9621));
    SetEventFlagID(1055425233, OFF);
    ClearSpEffect(10000, 1627130);
    EndIf(EventFlag(1055420915));
    RestartEvent();
});

// Refresh the granted permission without restarting its three-second warm-up.
$Event(5750405, Restart, function() {
    DisableNetworkSync();
    EndIf(!PlayerIsInOwnWorld());
    WaitFor(EventFlag(1055420915) || EventFlag(1055425233));
    EndIf(EventFlag(1055420915));
    if (EventFlag(1055425233) && EventFlag(1055420930) && CharacterHPValue(10000) > 0
        && CharacterHPValue(18002354) > 0
        && InArea(10000, 18000359) && !InArea(10000, 18002367)
        && !EventFlag(1055425042) && !CharacterHasSpEffect(10000, 100690)
        && !CharacterHasSpEffect(10000, 9621)) {
        SetSpEffect(10000, 1627130);
    } else {
        ClearSpEffect(10000, 1627130);
    }
    WaitFixedTimeSeconds(0.1);
    RestartEvent();
});


// Prepare the saved-loss baseline on map load and respawn, before entering the room.
// A retreat never rearms this controller; only the active encounter admits HP additions.
$Event(5750404, Restart, function() {
    BatchSetEventFlags(1055425100, 1055425195, OFF);
    BatchSetEventFlags(1055425262, 1055425273, OFF);
    SetEventFlagID(1055422996, OFF);
    SetEventFlagID(1055422997, OFF);
    WaitFixedTimeFrames(1); // Let position workers observe the reset before rearming.
    EndIf(EventFlag(1055420915) || EventFlag(1055420918));
    WaitFor((CharacterHPValue(10000) > 0 && !EventFlag(1055425042))
        || EventFlag(1055420915) || EventFlag(1055420918));
    EndIf(EventFlag(1055420915) || EventFlag(1055420918));
    if (EventFlag(1055420956)) { SetEventFlagID(1055425272, ON); }
    else if (EventFlag(1055420955)) { SetEventFlagID(1055425271, ON); }
    else if (EventFlag(1055420954)) { SetEventFlagID(1055425270, ON); }
    else if (EventFlag(1055420953)) { SetEventFlagID(1055425269, ON); }
    else if (EventFlag(1055420952)) { SetEventFlagID(1055425268, ON); }
    else if (EventFlag(1055420934)) { SetEventFlagID(1055425267, ON); }
    else if (EventFlag(1055420933)) { SetEventFlagID(1055425266, ON); }
    else if (EventFlag(1055420932)) { SetEventFlagID(1055425265, ON); }
    else if (EventFlag(1055420931)) { SetEventFlagID(1055425264, ON); }
    else if (EventFlag(1055420930)) { SetEventFlagID(1055425263, ON); }
    else { SetEventFlagID(1055425262, ON); }
    SetEventFlagID(1055422997, ON);
    WaitFor(EventFlag(1055425042) || EventFlag(1055420915) || EventFlag(1055420918));
    if (EventFlag(1055425042)) {
        // Reset on recovery/respawn, not while the death camera is still visible.
        WaitFor(CharacterHPValue(10000) > 0 || EventFlag(1055420915) || EventFlag(1055420918));
        EndIf(EventFlag(1055420915) || EventFlag(1055420918));
        RestartEvent();
    }
    if (EventFlag(1055420915)) {
        BatchSetEventFlags(1055425100, 1055425195, ON);
    }
    SetEventFlagID(1055422996, ON);
    SetEventFlagID(1055422997, OFF);
    EndIf(EventFlag(1055420915) || EventFlag(1055420918));
    WaitFor(EventFlag(1055425042) || EventFlag(1055420915) || EventFlag(1055420918));
    EndIf(EventFlag(1055420915) || EventFlag(1055420918));
    WaitFor(CharacterHPValue(10000) > 0 || EventFlag(1055420915) || EventFlag(1055420918));
    EndIf(EventFlag(1055420915) || EventFlag(1055420918));
    RestartEvent();
});

// Reversible diagnostics: latch each marker independently until map initialization.
// Never feed these observation flags back into teleport eligibility.
$Event(5750434, Restart, function(markerEffect, observedFlag) {
    EndIf(!PlayerIsInOwnWorld());
    WaitFor(CharacterHasSpEffect(18002354, markerEffect));
    SetEventFlagID(observedFlag, ON);
    EndEvent();
});
